import "dotenv/config";
import { getSupabaseClient } from "../src/api/supabaseClient";
const client = getSupabaseClient\(\);

const cutoff = new Date\(Date.now\(\) - 24 * 60 * 60 * 1000\).toISOString\(\);

const PAGE_SIZE = 1000;
let all: any[] = [];
let offset = 0;
while \(true\) {
  const { data, error } = await client.from\("notes"\)
    .select\("note_id, tweet_id, bot_name, submitted_at, cn_status"\)
    .gte\("submitted_at", cutoff\)
    .order\("submitted_at", { ascending: false }\)
    .range\(offset, offset + PAGE_SIZE - 1\);
  if \(error\) { console.error\(error\); break; }
  if \(!data || data.length === 0\) break;
  all.push\(...data\);
  if \(data.length < PAGE_SIZE\) break;
  offset += PAGE_SIZE;
}

console.log\(`Notes submitted in last 24h: ${all.length}\\n`\);

const byBot: Record<string, any[]> = {};
for \(const n of all\) {
  const bot = n.bot_name || "unknown";
  if \(!byBot[bot]\) byBot[bot] = [];
  byBot[bot].push\(n\);
}

for \(const [bot, notes] of Object.entries\(byBot\).sort\(\(a, b\) => b[1].length - a[1].length\)\) {
  console.log\(`=== ${bot} \(${notes.length} notes\) ===`\);
  for \(const n of notes\) {
    const status = \(n.cn_status || "-"\).padEnd\(30\);
    const time = n.submitted_at?.slice\(0, 16\) || "";
    console.log\(`  ${time}  ${status}  https://x.com/i/status/${n.tweet_id}`\);
  }
  console.log\(\);
}
SCRIPT)
